import{partnerInfo}from'./partners.js';
import * as T from './vendor/three.module.min.js';import{GLTFLoader}from'./vendor/loaders/GLTFLoader.js';import{FORM_HEIGHTS,creatureAsset}from'./world-layout.js';
const selectedPartner=partnerInfo(new URLSearchParams(location.search).get('partner'));document.querySelector('h1').textContent=selectedPartner.name;document.title=selectedPartner.name+' · Movement Preview';const forms=document.querySelector('.forms');forms.innerHTML=Array.from({length:selectedPartner.previewMax+1},(_,level)=>`<button data-level="${level}" aria-pressed="false">${level}</button>`).join('');const message=document.querySelector('#message');
try{
const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;document.body.prepend(renderer.domElement);const scene=new T.Scene();scene.background=new T.Color('#9eae8c');scene.fog=new T.Fog('#9eae8c',5,12);const camera=new T.PerspectiveCamera(35,1,.01,25),target=new T.Vector3(0,.32,0);let yaw=.62,pitch=.3,distance=1.95,baseDistance=1.95,bodySpan=.8,fitDistance=1.95;function frameCamera(){fitDistance=Math.max(baseDistance,bodySpan/(2*Math.tan(35*Math.PI/360)*Math.max(.35,camera.aspect))*1.08);distance=fitDistance;}
scene.add(new T.HemisphereLight(0xfff4dc,0x567354,2.2));const sun=new T.DirectionalLight(0xffe1ab,3);sun.position.set(-2.5,5,3);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-2,right:2,top:2,bottom:-2,near:.1,far:12});sun.shadow.normalBias=.012;scene.add(sun);const ground=new T.Mesh(new T.CylinderGeometry(2.5,2.6,.15,64),new T.MeshStandardMaterial({color:'#819f69',roughness:.95}));ground.position.y=-.075;ground.receiveShadow=true;scene.add(ground);const ring=new T.Mesh(new T.TorusGeometry(.63,.008,5,64),new T.MeshStandardMaterial({color:'#c9c197',roughness:.8}));ring.rotation.x=-Math.PI/2;ring.position.y=.001;scene.add(ring);
let avatar=null,mixer=null,actions={},current=null,currentName='walk',jumpTime=null,loadId=0;
function dispose(root){root.traverse(o=>{o.geometry?.dispose();for(const m of o.material?Array.isArray(o.material)?o.material:[o.material]:[]){for(const t of Object.values(m))if(t?.isTexture)t.dispose();m.dispose();}});}
function select(id){const next=actions[id];if(!next||current===next&&['walk','idle'].includes(id))return;next.reset().setEffectiveWeight(1).play();if(current)current.crossFadeTo(next,.15,false);current=next;currentName=id;jumpTime=id==='jump'?0:null;for(const k of ['walk','idle','jump','strike','airstrike','turnstrike','hit','cast']){document.querySelector('#'+k).classList.toggle('on',k===id);document.querySelector('#'+k).setAttribute('aria-pressed',String(k===id));}}
async function loadLevel(level){const token=++loadId;message.textContent='Loading Level '+level+'…';message.classList.remove('hidden');try{const gltf=await new GLTFLoader().loadAsync(creatureAsset(level,selectedPartner.id));if(token!==loadId){dispose(gltf.scene);return;}const model=gltf.scene;model.updateMatrixWorld(true);const box=new T.Box3().setFromObject(model),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),height=FORM_HEIGHTS[level],scale=height/size.y;model.scale.setScalar(scale);model.position.set(-center.x*scale,-box.min.y*scale,-center.z*scale);const nextAvatar=new T.Group();nextAvatar.add(model);nextAvatar.rotation.y=-(gltf.parser.json.extras?.maximaLocomotion?.forwardYaw||0);model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});if(avatar){mixer.stopAllAction();mixer.uncacheRoot(avatar);scene.remove(avatar);dispose(avatar);}avatar=nextAvatar;scene.add(avatar);mixer=new T.AnimationMixer(avatar);actions=Object.fromEntries(gltf.animations.map(c=>[c.name.toLowerCase(),mixer.clipAction(c)]));current=null;jumpTime=null;for(const id of ['jump','strike','airstrike','turnstrike','hit','cast']){document.querySelector('#'+id).hidden=!actions[id];if(actions[id]){actions[id].setLoop(T.LoopOnce,1);actions[id].clampWhenFinished=true;}}if(actions.jump){actions.jump.setLoop(T.LoopOnce,1);actions.jump.clampWhenFinished=true;}select(currentName==='jump'?'idle':currentName);target.y=height*.48;baseDistance=1.95+level*.2;bodySpan=Math.hypot(size.x,size.z)*scale;frameCamera();document.querySelector('#form-label').textContent=`MAXIMA · LEVEL ${level}`;for(const button of document.querySelectorAll('[data-level]')){const selected=Number(button.dataset.level)===level;button.classList.toggle('on',selected);button.setAttribute('aria-pressed',String(selected));}message.classList.add('hidden');}catch(error){console.error(error);if(token===loadId){message.textContent='This form could not load. Select a level to try again.';}}}
for(const id of ['walk','idle','jump','strike','airstrike','turnstrike','hit','cast'])document.querySelector('#'+id).onclick=()=>select(id);for(const button of document.querySelectorAll('[data-level]'))button.onclick=()=>loadLevel(Number(button.dataset.level));
const requested=Number(new URLSearchParams(location.search).get('level')||0);await loadLevel(Number.isInteger(requested)&&requested>=0&&requested<=selectedPartner.previewMax?requested:0);
let down=null;renderer.domElement.style.touchAction='none';renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,yaw,pitch};renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(!down)return;yaw=down.yaw-(e.clientX-down.x)*.008;pitch=T.MathUtils.clamp(down.pitch+(e.clientY-down.y)*.006,.08,.95);});for(const n of ['pointerup','pointercancel'])renderer.domElement.addEventListener(n,()=>down=null);renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();distance=T.MathUtils.clamp(distance+e.deltaY*.001,fitDistance*.62,fitDistance*1.7);},{passive:false});function resize(){const top=document.querySelector('header').getBoundingClientRect().bottom+12,bottom=document.querySelector('footer').getBoundingClientRect().top-12,height=Math.max(120,bottom-top);renderer.domElement.style.position='absolute';renderer.domElement.style.top=top+'px';renderer.setSize(innerWidth,height);camera.aspect=innerWidth/height;camera.updateProjectionMatrix();frameCamera();}addEventListener('resize',resize);resize();const clock=new T.Clock();function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);if(document.hidden)return;mixer?.update(dt);if(current&&['strike','airstrike','turnstrike','hit','cast'].includes(currentName)&&current.time>=current.getClip().duration)select('idle');if(jumpTime!==null){jumpTime+=dt;const t=(jumpTime/.9-.15)/.63;avatar.position.y=(t>0&&t<1?2.16*t*(1-t):0);if(jumpTime>=.9){select('idle');avatar.position.y=0;}}else if(avatar)avatar.position.y=0;camera.position.set(Math.sin(yaw)*Math.cos(pitch)*distance,target.y+Math.sin(pitch)*distance,Math.cos(yaw)*Math.cos(pitch)*distance);camera.lookAt(target);renderer.render(scene,camera);}animate();
}catch(e){console.error(e);for(const button of document.querySelectorAll('button'))button.disabled=true;message.textContent='This preview needs WebGL 3D graphics. Open it in a browser with 3D graphics acceleration available. The game package includes the animated model.';}
